/** Finite actual-kernel coverage for official 1.3.3 guard/pharmacist deck.
 * No arbitrary mutation of game state: every prefix is generated by actual
 * rules, actions, phase transitions, vote commits and persisted archives.
 * Read-only adjudicator enumeration is explicitly distinguished from commits. */
import test from 'node:test';
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {withKernel} from '../dist/backend/src/game/archive.js';
import {pharmacistWindow} from '../dist/backend/src/official/final-pack.js';
import {adjudicateOfficialVote} from '../dist/backend/src/engine/vote-adjudicator.js';
import {isS15VoteBlocked} from '../dist/backend/src/official/s13-mechanics.js';
import {ownCapabilities} from '../dist/backend/src/official/capabilities.js';
import {resolveCertifiedVictory} from '../dist/backend/src/official/victory-resolver.js';
const roles=[25,31,48,74,87],villagers=roles.filter(r=>r!==48),g='five-player-finite',id=String;
const ids=a=>a.map(id).sort();const living=s=>s.participants.filter(p=>p.life==='ALIVE').map(p=>p.currentCharacterId);
const dead=s=>s.participants.filter(p=>p.life==='DEAD_FINAL').map(p=>p.currentCharacterId).sort((a,b)=>a-b);
const subsets=(a)=>[[],...a.map(x=>[x]),...a.flatMap((x,i)=>a.slice(i+1).map(y=>[x,y]))];
function submit(e,r,skill,targets,key=randomUUID()){const s=e.getInternalState(g);return e.submit({actionId:key,idempotencyKey:key,gameId:g,playerId:id(r),skillId:skill,targetIds:targets.map(id),phase:s.phase,round:s.round,timestamp:1,payload:{},ruleVersion:s.ruleVersion});}
function begin(){return withKernel(undefined,false,(e)=>{e.createGame('five-player-normal',roles.map(r=>({playerId:id(r),characterId:r})),{gameId:g,seed:'five-player-finite-proof'});e.transition(g,'ROLE_ASSIGNED');e.transition(g,'NIGHT_COLLECT');return {gameId:g};},true);}
function step(a,fn){const r=withKernel(a.archive,false,(e,repo)=>{fn(e,repo);return {gameId:g};},true);assert(r.replay.verified);return r;}
function vote(e,entries=[]){e.openVoting(g);for(const [r,t] of entries){const key=randomUUID();e.submitVoteIntent(g,id(r),t===''?'':id(t),key,key,e.getInternalState(g).revision);}e.closeVoting(g);}
function startNight(e,bites=[],guard=null,sedative=null,reverse=false){const actions=[];if(guard!==null)actions.push(()=>submit(e,31,'official.31.guard',[guard]));if(bites.length)actions.push(()=>submit(e,48,'official.48.pack-bite',bites));if(sedative!==null)actions.push(()=>submit(e,87,'official.87.sedative',[sedative]));if(reverse)actions.reverse();for(const a of actions)a();e.transition(g,'NIGHT_RESOLVE');e.resolve(g);if(pharmacistWindow(e.getInternalState(g)))e.transition(g,'WITCH_WINDOW');}
function closeNight(e,rescue=null){if(e.getInternalState(g).phase==='WITCH_WINDOW'){if(rescue!==null)submit(e,87,'official.87.rescue',[rescue]);e.resolve(g);}e.transition(g,'NIGHT_FINALIZE');const v=e.completeVerifiedKnightSolo(g);if(!v.completed&&(!v.resolutionStatus||v.resolutionStatus==='CONTINUE'))e.transition(g,'DAY_DISCUSS');}
function normalNight(e,b=[],guard=null,rescue=null,sedative=null){startNight(e,b,guard,sedative);closeNight(e,rescue);}
function prefix(initial,removed,cause,spent){return step(initial,(e)=>{if(spent){normalNight(e,[87],null,87);vote(e);}if(!removed.length)return;if(cause==='night'){normalNight(e,removed);assert.equal(e.getInternalState(g).phase,'DAY_DISCUSS');vote(e);}else for(const r of removed){normalNight(e);vote(e,[[48,r]]);}assert.deepEqual(dead(e.getInternalState(g)),[...removed].sort((a,b)=>a-b));});}
function verifyNight(s,expected){assert.deepEqual(dead(s),[...expected].sort((a,b)=>a-b));if(expected.length>=3){assert.equal(s.phase,'GAME_COMPLETED');assert.deepEqual(s.winnerIds,['48']);}else{assert.equal(s.phase,'DAY_DISCUSS');assert.equal(s.completed,false);}}
function env(fn){const old=process.env.WV_ARCHIVED_RULE_REGRESSION;delete process.env.WV_ARCHIVED_RULE_REGRESSION;try{return fn();}finally{if(old===undefined)delete process.env.WV_ARCHIVED_RULE_REGRESSION;else process.env.WV_ARCHIVED_RULE_REGRESSION=old;}}

test('Five-player guard/pharmacist finite kernel: all living masks, both removal paths, fresh/spent rescue, 0/1/2 attacks and every legal rescue target',()=>env(()=>{
 const initial=begin();let prefixes=0,branches=0,windows=0;
 for(const removed of subsets(villagers))for(const cause of (removed.length?['night','hanging']:['night']))for(const spent of [false,true]){
  const base=prefix(initial,removed,cause,spent);assert.equal(base.state.phase,'NIGHT_COLLECT');prefixes++;const alive=living(base.state),guards=alive.includes(31)?[null,...alive]:[null],targets=alive.filter(r=>r!==48);
  for(const guard of guards)for(const bite of subsets(targets)){
   const pre=step(base,(e,repo)=>{startNight(e,bite,guard,null,branches%2===1);const s=e.getInternalState(g),hit=bite.filter(r=>r!==guard);if(alive.includes(87)){assert.equal(s.phase,'WITCH_WINDOW');assert.deepEqual(s.participants.filter(p=>p.life==='PENDING_DEATH').map(p=>p.currentCharacterId).sort((a,b)=>a-b),[...hit].sort((a,b)=>a-b));assert.equal(s.completed,false);assert.notEqual(resolveCertifiedVictory(s,repo.events(g),0).kind,'WINNER_VERIFIED');const cap=ownCapabilities(s,'87').find(x=>x.skillId==='official.87.rescue');if(!spent&&hit.length){assert(cap?.available);assert.deepEqual([...cap.eligibleTargetIds].sort(),ids(hit));}else assert(!cap?.available);windows++;}else{assert.equal(s.phase,'NIGHT_RESOLVE');assert.equal(s.participants.some(p=>p.life==='PENDING_DEATH'),false);}});
   const hit=bite.filter(r=>r!==guard),rescues=alive.includes(87)&&!spent?[null,...hit]:[null];
   for(const rescue of rescues){const result=step(pre,(e)=>{closeNight(e,rescue);verifyNight(e.getInternalState(g),[...removed,...hit.filter(r=>r!==rescue)]);});assert(result.replay.verified);branches++;}
  }
 }
 assert.equal(prefixes,42);assert(branches>1000&&windows>500,`${branches}/${windows}`);console.log('FIVE_GUARD_PHARMACIST_FINITE '+JSON.stringify({prefixes,branches,windows,actualKernel:true,normalRuleVersion:initial.state.ruleVersion}));
}));

test('Five-player guard/pharmacist finite kernel: every cooldown target, invalid target/resource and voting commit classes',()=>env(()=>{
 const initial=begin();let branches=0;
 for(const previous of roles){const base=step(initial,e=>{normalNight(e,[],previous);vote(e);});
  const rejected=step(base,e=>{assert.throws(()=>submit(e,31,'official.31.guard',[previous]),x=>x.code==='TARGET_INVALID');});assert.equal(rejected.state.round,2);
  for(const next of [null,...roles.filter(r=>r!==previous)]){const r=step(base,e=>{normalNight(e,[],next);vote(e);if(next!==previous)submit(e,31,'official.31.guard',[previous]);});assert(r.replay.verified);branches++;}
 }
 // Commit all actual day outcome classes on every reachable living mask;
 // include one actual active sedative for each eligible non-self target.
 for(const removed of subsets(villagers)){
  const base=prefix(initial,removed,'night',false),alive=living(base.state);
  for(const sed of [null,...(alive.includes(87)?alive.filter(r=>r!==87):[])]){
   const day=step(base,e=>normalNight(e,[],null,null,sed));const voters=alive.filter(r=>r!==sed);const candidates=[[],...alive.map(t=>[[voters[0],t]]),...(voters.length>=2?[[[voters[0],alive[0]],[voters[1],alive[1]]]]:[])];
   for(const votes of candidates){const result=step(day,e=>{vote(e,votes);const s=e.getInternalState(g);if(votes.length!==1){assert.equal(s.phase,'NIGHT_COLLECT');assert.equal(s.completed,false);return;}const target=votes[0][1];assert(dead(s).includes(target));if(target===48){assert(s.completed);assert.deepEqual([...s.winnerIds].sort(),ids(villagers));}else if(alive.length===3){assert(s.completed);assert.deepEqual(s.winnerIds,['48']);}else assert.equal(s.phase,'NIGHT_COLLECT');});assert(result.replay.verified);branches++;}
   if(sed!==null)step(day,e=>{e.openVoting(g);const key=randomUUID();assert.throws(()=>e.submitVoteIntent(g,id(sed),'48',key,key,e.getInternalState(g).revision));});
  }
 }
 assert(branches>100);console.log('FIVE_GUARD_COOLDOWN_VOTE_COMMIT '+branches);
}));

test('Five-player guard/pharmacist finite adjudicator: every legal ballot assignment by reachable living mask and active sedative',()=>env(()=>{
 const initial=begin();let count=0,states=0;
 for(const removed of subsets(villagers)){
  const base=prefix(initial,removed,'night',false),alive=living(base.state);
  for(const sed of [null,...(alive.includes(87)?alive.filter(r=>r!==87):[])]){
   const day=step(base,e=>{normalNight(e,[],null,null,sed);e.openVoting(g);});const s=day.state,voters=alive.filter(r=>!isS15VoteBlocked(s,id(r)));assert.deepEqual(voters,alive.filter(r=>r!==sed));states++;const opts=[null,'',...alive.map(id)];
   function walk(i,ballots){if(i<voters.length){for(const t of opts)walk(i+1,[...ballots,t]);return;}const intents=ballots.flatMap((t,j)=>t===null?[]:[{voterId:id(voters[j]),targetId:t,ballotId:`b${j}`,idempotencyKey:`k${j}`}]);const result=adjudicateOfficialVote({...s,voting:{...s.voting,intents}}).outcome;const counts=alive.map(r=>[id(r),ballots.filter(t=>t===id(r)).length]),max=Math.max(...counts.map(x=>x[1])),leaders=counts.filter(x=>x[1]===max);assert.equal(result.kind,max===0?'NO_HANGING_ZERO':leaders.length>1?'NO_HANGING_TIE':'HANGING_AUTHORIZED');if(max&&leaders.length===1)assert.equal(result.targetId,leaders[0][0]);count++;}walk(0,[]);
  }
 }
 assert(states>20&&count>30000);console.log('FIVE_GUARD_BALLOT_MATRIX '+JSON.stringify({states,count}));
}));

test('Five-player guard/pharmacist reduced history: dead prior guard target, invalid actions and once-only resources',()=>env(()=>{
 const initial=begin(),base=step(initial,e=>{normalNight(e,[],25);vote(e,[[48,25]]);});
 step(base,e=>{assert.throws(()=>submit(e,31,'official.31.guard',[25]));assert.throws(()=>submit(e,48,'official.48.pack-bite',[25]));assert.throws(()=>submit(e,48,'official.48.pack-bite',[74,74]));assert.throws(()=>submit(e,48,'official.48.pack-bite',[48]));assert.throws(()=>submit(e,87,'official.87.sedative',[87]));assert.throws(()=>submit(e,87,'official.87.sedative',[25]));startNight(e,[87],31,48,true);const s=e.getInternalState(g);assert.equal(s.phase,'WITCH_WINDOW');assert.throws(()=>submit(e,87,'official.87.rescue',[25]));assert.throws(()=>submit(e,87,'official.87.rescue',[31]));closeNight(e,87);assert.deepEqual(dead(e.getInternalState(g)),[25]);assert(isS15VoteBlocked(e.getInternalState(g),'48'));vote(e);assert.throws(()=>submit(e,87,'official.87.sedative',[48]));normalNight(e,[74],74);assert.deepEqual(dead(e.getInternalState(g)),[25]);assert(!isS15VoteBlocked(e.getInternalState(g),'48'));vote(e);startNight(e,[87]);assert.throws(()=>submit(e,87,'official.87.rescue',[87]));closeNight(e);assert.deepEqual(dead(e.getInternalState(g)),[25,87]);});
}));
